#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."

export RAILS_ENV="${RAILS_ENV:-production}"
export PORT="${PORT:-3000}"

mkdir -p storage tmp/pids tmp/cache log

echo "Preparing database..."
bundle exec rails db:prepare

echo "Preparing assets..."
bundle exec rails assets:precompile

echo "Starting Quizzy on 0.0.0.0:${PORT}"
exec bundle exec rails server --binding 0.0.0.0 --port "${PORT}"
