<script>
  (function () {
    var POLL_MS = 50;
    var epoch = 0;
    var submitting = false;
    var armToken = 0;

    function liveRoot() {
      return document.querySelector("[data-live-root]");
    }

    function parseRoot(html) {
      var doc = new DOMParser().parseFromString(html, "text/html");
      return doc.querySelector("[data-live-root]");
    }

    function sameStructure(current, next) {
      return current.getAttribute("data-phase") === next.getAttribute("data-phase")
        && current.getAttribute("data-question") === next.getAttribute("data-question")
        && current.getAttribute("data-pick") === next.getAttribute("data-pick")
        && current.getAttribute("data-player") === next.getAttribute("data-player")
        && current.getAttribute("data-winners") === next.getAttribute("data-winners");
    }

    function updateTexts(current, next) {
      var incoming = next.querySelectorAll("[data-live-text]");
      var grouped = {};
      for (var i = 0; i < incoming.length; i++) {
        var key = incoming[i].getAttribute("data-live-text");
        if (!grouped[key]) grouped[key] = [];
        grouped[key].push(incoming[i].textContent);
      }
      Object.keys(grouped).forEach(function (key) {
        var dests = current.querySelectorAll('[data-live-text="' + key + '"]');
        var values = grouped[key];
        for (var j = 0; j < dests.length && j < values.length; j++) {
          if (dests[j].textContent !== values[j]) dests[j].textContent = values[j];
        }
      });
      current.setAttribute("data-version", next.getAttribute("data-version"));
    }

    function navigationTransit() {
      try {
        var nav = performance.getEntriesByType("navigation")[0];
        if (!nav) return 0;
        return Math.max(0, nav.responseStart - nav.requestStart);
      } catch (e) {
        return 0;
      }
    }

    // Question open is scheduled a fraction of a second ahead so every screen
    // reveals it together. Speed ties use that shared open moment.
    function armOpen(node, transit) {
      armToken += 1;
      var token = armToken;
      if (!node) return;
      var opensAt = Number(node.getAttribute("data-opens-at") || "");
      var serverNow = Number(node.getAttribute("data-server-now") || "");
      if (!opensAt || !serverNow) {
        node.removeAttribute("data-pending-open");
        return;
      }
      var delay = opensAt - serverNow - Math.max(0, transit || 0);
      if (!(delay > 15)) {
        node.removeAttribute("data-pending-open");
        return;
      }
      node.setAttribute("data-pending-open", "1");
      setTimeout(function () {
        if (token !== armToken) return;
        var current = liveRoot();
        if (current) current.removeAttribute("data-pending-open");
      }, delay);
    }

    function applyHtml(html, transit) {
      var current = liveRoot();
      if (!current || !html) return;
      var next = parseRoot(html);
      if (!next) return;
      if (sameStructure(current, next)) {
        if (current.getAttribute("data-version") !== next.getAttribute("data-version")) updateTexts(current, next);
        return;
      }
      var imported = document.importNode(next, true);
      current.replaceWith(imported);
      armOpen(imported, transit);
    }

    function pollUrl(node) {
      var url = node.getAttribute("data-poll-url");
      if (!url) return "";
      var version = node.getAttribute("data-version") || "";
      var sep = url.indexOf("?") >= 0 ? "&" : "?";
      return url + sep + "v=" + encodeURIComponent(version) + "&_=" + Date.now();
    }

    function readBody(response, sentAt) {
      var rtt = Date.now() - sentAt;
      if (response.status === 204) return { html: "", rtt: rtt };
      if (!response.ok) return { html: "", rtt: rtt };
      return response.text().then(function (html) {
        return { html: html, rtt: rtt };
      });
    }

    function tick() {
      var node = liveRoot();
      if (!node || submitting) {
        setTimeout(tick, POLL_MS);
        return;
      }
      var url = pollUrl(node);
      if (!url) {
        setTimeout(tick, POLL_MS);
        return;
      }
      var epochAtStart = epoch;
      var sentAt = Date.now();
      fetch(url, {
        credentials: "same-origin",
        cache: "no-store",
        headers: { "Accept": "text/html", "X-Quizzy-Live": "1" }
      }).then(function (response) {
        return readBody(response, sentAt);
      }).then(function (payload) {
        if (epochAtStart === epoch && !submitting && payload && payload.html) {
          applyHtml(payload.html, payload.rtt / 2);
        }
      }).catch(function () {
        // Crowded conference Wi-Fi drops requests. The next tick tries again.
      }).then(function () {
        setTimeout(tick, POLL_MS);
      });
    }

    document.addEventListener("submit", function (event) {
      var form = event.target;
      if (!form || !form.closest || !form.closest("[data-live-root]")) return;
      if (form.getAttribute("data-live-bypass") === "1") return;
      event.preventDefault();
      submitting = true;
      epoch += 1;
      var epochAtStart = epoch;
      var data = new FormData(form);
      var submitter = event.submitter;
      if (submitter && submitter.name && !data.has(submitter.name)) {
        data.append(submitter.name, submitter.value);
      }
      var sentAt = Date.now();
      fetch(form.action, {
        method: (form.getAttribute("method") || "post").toUpperCase(),
        body: data,
        credentials: "same-origin",
        headers: { "Accept": "text/html", "X-Quizzy-Live": "1" }
      }).then(function (response) {
        if (response.status === 401 || response.status === 403) {
          form.setAttribute("data-live-bypass", "1");
          form.submit();
          return { html: "", rtt: 0 };
        }
        return readBody(response, sentAt);
      }).then(function (payload) {
        if (epochAtStart === epoch && payload && payload.html) applyHtml(payload.html, payload.rtt / 2);
      }).catch(function () {
        form.setAttribute("data-live-bypass", "1");
        form.submit();
      }).then(function () {
        submitting = false;
      });
    });

    armOpen(liveRoot(), navigationTransit());
    if (liveRoot()) tick();
  })();
</script>
